+            <div class="text-success mb-3" style="font-size: 3rem;">✓</div>
+            <h3 class="card-title text-success">Application Submitted!</h3>
+            <p class="card-text mt-3">Your application has been received.</p>
+            <p class="card-text"><strong>Application ID: @_applicationId</strong></p>
+        </div>
+    </div>
+}
+else
+{
+    <!-- Step Indicator Bar -->
+    <nav class="mb-4">
+        <div class="d-flex justify-content-between position-relative">
+            @for (int i = 0; i < _stepNames.Length; i++)
+            {
+                var stepIndex = i;
+                var isCompleted = stepIndex < _currentStep;
+                var isCurrent = stepIndex == _currentStep;
+                var isFuture = stepIndex > _currentStep;
+
+                <div class="text-center flex-fill position-relative">
+                    <button type="button"
+                            class="btn rounded-circle d-inline-flex align-items-center justify-content-center @(isCurrent ? "btn-primary" : isCompleted ? "btn-success" : "btn-outline-secondary")"
+                            style="width: 40px; height: 40px; font-size: 0.85rem;"
+                            disabled="@isFuture"
+                            @onclick="() => GoToStep(stepIndex)">
+                        @if (isCompleted)
+                        {
+                            <span>✓</span>
+                        }
+                        else
+                        {
+                            <span>@(stepIndex + 1)</span>
+                        }
+                    </button>
+                    <div class="mt-1 small @(isFuture ? "text-muted" : isCurrent ? "fw-bold text-primary" : "text-success")">
+                        @_stepNames[stepIndex]
+                    </div>
+                </div>
+            }
+        </div>
+    </nav>
+
+    @if (!string.IsNullOrEmpty(_errorMessage))
+    {
+        <div class="alert alert-danger alert-dismissible fade show" role="alert">
+            @_errorMessage
+            <button type="button" class="btn-close" @onclick="() => _errorMessage = null"></button>
+        </div>
+    }
+
+    <!-- Step Content -->
+    @switch (_currentStep)
+    {
+        case 0:
+            <StepPersonalInfo FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
+                              FullNameChanged="v => _fullName = v" EmailChanged="v => _email = v"
+                              PhoneChanged="v => _phone = v" AddressChanged="v => _address = v" />
+            <div class="d-flex justify-content-end mt-3">
+                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
+                    @if (_isValidating) { <span class="spinner-border spinner-border-sm me-1"></span> }
+                    Next
+                </button>
+            </div>
+            break;
+
+        case 1:
+            <StepWorkHistory Entries="_workEntries" />
+            <div class="d-flex justify-content-between mt-3">
+                <button class="btn btn-outline-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
+            </div>
+            break;
+
+        case 2:
+            <StepReferences References="_references" />
+            <div class="d-flex justify-content-between mt-3">
+                <button class="btn btn-outline-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
+            </div>
+            break;
+
+        case 3:
+            <StepCoverLetter CoverLetter="@_coverLetter" CoverLetterChanged="v => _coverLetter = v" MaxLength="2000" />
+            <div class="d-flex justify-content-between mt-3">
+                <button class="btn btn-outline-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
+            </div>
+            break;
+
+        case 4:
+            <StepReview FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
+                        WorkEntries="_workEntries" References="_references" CoverLetter="@_coverLetter"
+                        OnEditStep="GoToStep" />
+            <div class="d-flex justify-content-between mt-3">
+                <button class="btn btn-outline-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-success" @onclick="SubmitApplication" disabled="@_isSubmitting">
+                    @if (_isSubmitting) { <span class="spinner-border spinner-border-sm me-1"></span> }
+                    Submit Application
+                </button>
+            </div>
+            break;
+    }
+}
+
+@code {
+    private static readonly string[] _stepNames = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];
+
+    private int _currentStep;
+    private string? _errorMessage;
+    private bool _isValidating;
+    private bool _isSubmitting;
+    private bool _submitted;
+    private int _applicationId;
+
+    // Step 1 state
+    private string _fullName = "";
+    private string _email = "";
+    private string _phone = "";
+    private string _address = "";
+
+    // Step 2 state
+    private List<WorkEntryModel> _workEntries = [new()];
+
+    // Step 3 state
+    private List<ReferenceModel> _references = [new(), new()];
+
+    // Step 4 state
+    private string _coverLetter = "";
+
+    private void GoToStep(int step)
+    {
+        if (step < _currentStep)
+        {
+            _errorMessage = null;
+            _currentStep = step;
+        }
+    }
+
+    private void PreviousStep()
+    {
+        _errorMessage = null;
+        if (_currentStep > 0) _currentStep--;
+    }
+
+    private async Task NextFromPersonalInfo()
+    {
+        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
+            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
+        {
+            _errorMessage = "Please fill in all fields.";
+            return;
+        }
+
+        _isValidating = true;
+        _errorMessage = null;
+        try
+        {
+            var valid = await ApplicationService.ValidateEmailAsync(_email);
+            if (!valid)
+            {
+                _errorMessage = "Please enter a valid email address.";
+                return;
+            }
+            _currentStep = 1;
+        }
+        finally
+        {
+            _isValidating = false;
+        }
+    }
+
+    private void NextFromWorkHistory()
+    {
+        foreach (var entry in _workEntries)
+        {
+            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
+                || entry.StartDate == default)
+            {
+                _errorMessage = "Please fill in company, title, and start date for all work entries.";
+                return;
+            }
+        }
+        _errorMessage = null;
+        _currentStep = 2;
+    }
+
+    private void NextFromReferences()
+    {
+        foreach (var r in _references)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
+                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
+            {
+                _errorMessage = "Please fill in all fields for each reference.";
+                return;
+            }
+        }
+        _errorMessage = null;
+        _currentStep = 3;
+    }
+
+    private void NextFromCoverLetter()
+    {
+        if (string.IsNullOrWhiteSpace(_coverLetter))
+        {
+            _errorMessage = "Please write a cover letter.";
+            return;
+        }
+        _errorMessage = null;
+        _currentStep = 4;
+    }
+
+    private async Task SubmitApplication()
+    {
+        _isSubmitting = true;
+        _errorMessage = null;
+        try
+        {
+            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
+            var workHistory = new WorkHistory(_workEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
+            var refs = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+            var application = new JobApplication(personal, workHistory, refs, _coverLetter);
+
+            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            _submitted = true;
+        }
+        catch
+        {
+            _errorMessage = "An error occurred while submitting. Please try again.";
+        }
+        finally
+        {
+            _isSubmitting = false;
+        }
+    }
+
+    // Mutable models used for two-way binding in the form
+    public class WorkEntryModel
+    {
+        public string Company { get; set; } = "";
+        public string Title { get; set; } = "";
+        public DateTime StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = "";
+    }
+
+    public class ReferenceModel
+    {
+        public string Name { get; set; } = "";
+        public string Relationship { get; set; } = "";
+        public string Email { get; set; } = "";
+        public string Phone { get; set; } = "";
+    }
+}
+

